const style=node('style');style.textContent='.fc-testimonial-reward{box-sizing:border-box;max-width:1080px;margin:24px auto;padding:clamp(20px,3vw,32px);border:1px solid #dcd6bc;border-radius:24px;background:linear-gradient(125deg,#fbf0d3,#faf8ef 50%,#e4eedf);color:#254e3e;font:15px/1.8 Arial,"Microsoft YaHei",sans-serif}.fc-testimonial-reward h2{font-size:clamp(24px,3vw,33px);line-height:1.4;margin:8px 0 14px}.fc-testimonial-reward p{margin:12px 0}.fc-testimonial-reward a,.fc-testimonial-reward button{display:inline-flex;align-items:center;min-height:44px;margin:7px 10px 7px 0;padding:10px 20px;border-radius:24px;border:1px solid #73917a;font:inherit;cursor:pointer;background:#285541;color:#fff;text-decoration:none}.fc-testimonial-reward .small{font-size:12px;color:#5c715d}.fc-testimonial-reward small{color:#9b762b;font-weight:700}.fc-testimonial-reward :focus-visible{outline:3px solid #b88c36;outline-offset:3px}@media(max-width:540px){.fc-testimonial-reward{margin:16px 8px}.fc-testimonial-reward a,.fc-testimonial-reward button{width:100%;justify-content:center}}';document.head.append(style);
function showDiscussion(status){const discuss=Array.from(document.querySelectorAll('[role="tab"]')).find(n=>/Discuss|讨论/i.test(n.textContent));if(!discuss){status.textContent=t('请打开侧栏的讨论区分享，找不到时请联系 FC。','Open Discuss in the sidebar to share. Contact FC if it is unavailable.');return;}document.querySelector('[aria-label="Expand sidebar"]')?.click();discuss.click();status.textContent=t('请在原有讨论输入框写下真实感受，再自行按分享发布。','Write your honest experience in the original discussion input and choose Share yourself.');setTimeout(()=>{const p=Array.from(document.querySelectorAll('[role="tabpanel"]')).find(p=>p.getClientRects().length&&/discuss|讨论/i.test(p.getAttribute('aria-label')||document.getElementById(p.getAttribute('aria-labelledby'))?.textContent||''));p?.querySelector('[contenteditable="true"],textarea')?.focus();},220);}
function render(r){root.replaceChildren();root.lang=lang==='zh'?'zh-Hans':'en';root.setAttribute('aria-label',t('FC 见证积分与礼物','FC testimonial points and rewards'));root.append(node('small',t('FC 会员专属 · 分享积分','FC MEMBER REWARDS')),node('h2',t('分享真实感受，把积分换成心意。','Real experiences. Rewards to choose.')),node('p',t('每份经人工核实的真实原创见证，可获 10 积分。累积积分，自由选择免费天数或礼物。','Each genuine, original testimonial verified by FC earns 10 points. Save your points for free membership days or gifts.')));
if(r){root.append(node('p',t('本次音疗：','This audio: ')+(lang==='zh'?r.z:r.n)));const b=node('button',t('分享这首音疗的感受','Share my experience of this audio')),status=node('p');status.setAttribute('role','status');b.type='button';b.onclick=()=>showDiscussion(status);root.append(b);const a=node('a',t('查看积分／提交核实／兑换礼物 ↗','My points / verification / rewards ↗'));a.href=BASE+'?lang='+lang+'&audio='+encodeURIComponent('https://frequencies-clinic.learnworlds.com/path-player?courseid='+r.c+'&unit='+r.u+'Unit');a.target='_blank';a.rel='noopener noreferrer';root.append(a,status);}else{const a=node('a',t('打开我的积分与礼物 ↗','Open my points & rewards ↗'));a.href=BASE+'?lang='+lang;a.target='_blank';a.rel='noopener noreferrer';root.append(a);}
root.append(node('p',t('已付款、账户有效且积分足够，即可申请，无需等续费。剩余积分在账户有效期间继续累积；客服确认库存和安排。寄送邮费 RM9 由顾客承担。','Paid members with an active account and enough points can apply without waiting for renewal. Unused points accumulate while active. Customer service confirms stock and fulfilment. Customers pay RM9 shipping.')));
const privacy=node('p',t('评论按 FC 原有讨论区设置展示。只分享愿意公开的感受，不必提交病历。提交核实申请不会自动加分；打卡与旧已核准奖励另行保留，同一见证不重复领奖。','Comments use FC’s existing discussion visibility. Share only what you are comfortable disclosing; medical reports are not required. Submitting a request does not automatically award points. Check-in and already approved legacy rewards remain separate; each testimonial earns once.'));privacy.className='small';root.append(privacy);}
function refresh(){const here=new URL(location.href);const r=RECORDINGS.find(r=>r.c===here.searchParams.get('courseid')&&r.u===(here.searchParams.get('unit')||'').replace(/Unit$/,''));if(!home&&!r){root?.remove();root=null;current='';return;}const key=home?'home':r.c+'/'+r.u;if(root?.isConnected&&key===current)return;const target=home?(document.querySelector('main')||document.body):document.getElementById('playerFrame');if(!target)return;root?.remove();root=node('section');root.className='fc-testimonial-reward';root.id='fc-testimonial-reward';if(home)target.prepend(root);else target.after(root);current=key;render(r);}
window.addEventListener('fc:language',e=>{lang=e.detail.language==='en'?'en':'zh';current='';refresh();});refresh();new MutationObserver(()=>{clearTimeout(timer);timer=setTimeout(refresh,120);}).observe(document.body,{childList:true,subtree:true});
